insert into public.timelines (slug, owner_id, title, description, category, language, visibility, share_id, start_year, end_year, cover_seed)
values ('culture-architecture', '00000000-0000-4000-8000-512d7b8348dc', '建築様式の進化', '鉄とガラスの時代からモダニズムの成立と批判、ポストモダン、そして木造回帰まで。様式の思想・技術と材料・都市と生活の3層を重ね、建築が各時代の社会にどう応えてきたかを静かに辿る年表です。', 'culture', 'ja', 'public', 's_culture-architecture', 1851, 2022, 'culture-architecture')
