          '1950-05-30', null, 'day', 'point', '文化財保護法が制定', '前年の法隆寺金堂壁画焼損を契機に、文化財保護法が制定されました。建造物や美術品に加え、演劇・音楽・工芸技術といった無形文化財の保護を、世界に先駆けて法制化した点が画期でした。

形あるモノではなく「技」そのものを保護対象とする発想は、のちの重要無形文化財保持者(人間国宝)制度に結実します。半世紀後のユネスコ無形文化遺産制度の先行モデルとも評される、日本発の制度設計です。', null,
          'verified', null, 'user', 2) returning id)
insert into public.event_sources (event_id, title, url) select ev.id, v.title, v.url from ev, (values ('Wikipedia: 文化財保護法', 'https://ja.wikipedia.org/wiki/文化財保護法')) as v(title, url);
