          '1955-01-01', null, 'year', 'point', '最初の人間国宝が認定される', '改正文化財保護法に基づき、最初の重要無形文化財保持者が認定されました。工芸技術の分野では、色絵磁器の富本憲吉、民芸陶器の濱田庄司、鉄釉陶器の石黒宗麿らが名を連ねています。

「人間国宝」の通称で知られるこの制度は、卓越した技を持つ個人を国が認定し、伝承者の養成を助成する仕組みです。ただし頂点の顕彰は、産地全体の雇用や流通の衰退(産地と職人レイヤー)とは別の問題を残しました。', null,
          'verified', null, 'user', 3) returning id)
insert into public.event_sources (event_id, title, url) select ev.id, v.title, v.url from ev, (values ('Wikipedia: 人間国宝', 'https://ja.wikipedia.org/wiki/人間国宝')) as v(title, url);
