  values ((select id from public.timelines where slug = 'culture-traditional-crafts'),
          (select id from public.layers where timeline_id = (select id from public.timelines where slug = 'culture-traditional-crafts') and name = '制度と保護'),
          '1974-05-25', null, 'day', 'point', '伝統的工芸品産業振興法(伝産法)公布', '100年以上続く技術・技法、主として日常生活で使われることなどを要件に、国が「伝統的工芸品」を指定して産地を支援する伝統的工芸品産業振興法が公布されました。翌年から指定が始まり、指定品目は現在240を超えています。

文化財保護法が技の頂点を守るのに対し、伝産法は産業としての裾野を支える設計で、日本の工芸保護の両輪が出揃いました。それでも従事者の減少(産地と職人レイヤー)は止まらず、制度の限界も同時に示していきます。', null,
          'verified', null, 'user', 4) returning id)
insert into public.event_sources (event_id, title, url) select ev.id, v.title, v.url from ev, (values ('Wikipedia: 伝統的工芸品', 'https://ja.wikipedia.org/wiki/伝統的工芸品')) as v(title, url);
