          '1977-01-01', null, 'year', 'point', '輪島塗が重要無形文化財に指定', '輪島塗の製作技術が国の重要無形文化財に指定され、輪島塗技術保存会が保持団体として認定されました。個人ではなく、産地の技術者集団を認定する方式です。

布着せや地の粉を使う堅牢な下地など、多数の工程を塗師・蒔絵師・沈金師らが分業で担う輪島の生産体制が、制度の上でも「集団の技」として位置づけられました。2024年の震災(同レイヤー)では、この分業構造そのものが危機に立たされます。', null,
          'verified', null, 'user', 5) returning id)
insert into public.event_sources (event_id, title, url) select ev.id, v.title, v.url from ev, (values ('Wikipedia: 輪島塗', 'https://ja.wikipedia.org/wiki/輪島塗')) as v(title, url);
with ev as (insert into public.events (timeline_id, layer_id, event_date, end_date, date_precision, event_type, title, summary, detail, credibility, credibility_note, origin, position)
  values ((select id from public.timelines where slug = 'culture-traditional-crafts'),
